import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  useLoaderData,
  createMemoryHistory,
} from '@tanstack/react-router';

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

export function SlowView() {
  const data = useLoaderData({ from: slowRoute.id });
  return <p>{data.value}</p>;
}

export const slowRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/slow',
  pendingMs: 0,
  pendingComponent: () => <p>loading</p>,
  loader: () =>
    new Promise<{ value: string }>((resolve) => setTimeout(() => resolve({ value: 'done' }), 50)),
  component: SlowView,
});

const routeTree = rootRoute.addChildren([slowRoute]);

export function makeRouter(initialEntries: string[] = ['/slow']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
